/**
 * Icon choices offered in the block editor (slug => label).
 */
function bricareau_icon_choices() {
	return array_keys( bricareau_icon_paths() + bricareau_filled_icon_paths() );
}

/**
 * Returns an inline SVG for the given icon slug ('' if unknown).
 *
 * @param string $name  Icon slug.
 * @param string $class CSS classes for the <svg>.
 * @param array  $args  Optional: 'stroke-width', 'fill' (true for filled star etc.).
 */
function bricareau_icon( $name, $class = 'w-6 h-6', $args = array() ) {
	$filled = bricareau_filled_icon_paths();
	if ( isset( $filled[ $name ] ) ) {
		return sprintf(
			'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 -960 960 960" fill="currentColor" class="%s" aria-hidden="true">%s</svg>',
			esc_attr( $class ),
			$filled[ $name ]
		);
	}

	$paths = bricareau_icon_paths();
	if ( ! isset( $paths[ $name ] ) ) {
		return '';
	}

	return sprintf(
		'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="%s" stroke="currentColor" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round" class="%s" aria-hidden="true">%s</svg>',
		empty( $args['fill'] ) ? 'none' : 'currentColor',
		esc_attr( $args['stroke-width'] ?? 2 ),
		esc_attr( $class ),
		$paths[ $name ]
	);
}
